async (page) => {
  const { execSync, spawn } = require('child_process');
  const fs = require('fs');

  const results = {};

  // Resolve the target /workspace path. If /workspace doesn't exist as a real
  // dir, fall back to /tmp/mcp-workspace/workspace.
  let workspaceDir = '/workspace';
  try {
    fs.accessSync(workspaceDir, fs.constants.W_OK);
  } catch (e) {
    workspaceDir = '/tmp/mcp-workspace/workspace';
  }
  results.workspaceDir = workspaceDir;

  const scriptPath = `${workspaceDir}/network_monitor.sh`;

  // Ensure the script exists at the resolved location (copy if needed)
  if (!fs.existsSync(scriptPath)) {
    fs.copyFileSync('/tmp/mcp-workspace/workspace/network_monitor.sh', scriptPath);
  }

  // Make executable
  execSync(`chmod +x ${scriptPath}`);
  results.permissions = execSync(`ls -l ${scriptPath}`).toString().trim();

  // Start in background, fully detached so it survives this call
  const child = spawn('/bin/bash', [scriptPath], {
    detached: true,
    stdio: 'ignore',
    cwd: workspaceDir,
  });
  child.unref();
  results.pid = child.pid;

  // Give it a moment so the startup line is written
  await new Promise(r => setTimeout(r, 1500));

  results.processCheck = execSync(`ps -p ${child.pid} -o pid,cmd= || echo "not running"`).toString().trim();
  try {
    results.logSoFar = fs.readFileSync(`${workspaceDir}/network_log.txt`, 'utf8');
  } catch (e) {
    results.logSoFar = `(no log yet: ${e.message})`;
  }

  return results;
}
